package com.travbook.railtickets.adapter.out.persistence;
import com.travbook.railtickets.application.port.out.RailTicketStore;
import com.travbook.railtickets.application.port.in.RailTickets.*;
import com.travbook.railtickets.domain.model.RailTicket.*;
import com.travbook.shared.domain.DomainFailure;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.transaction.support.TransactionTemplate;
import tools.jackson.databind.ObjectMapper;
import java.time.*;
import java.sql.Timestamp;
import java.util.*;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import static com.travbook.shared.domain.DomainFailure.Code.*;
public final class JdbcRailTicketStore implements RailTicketStore {
 private final JdbcClient jdbc;private final TransactionTemplate tx;private final ObjectMapper json;private final Clock clock;private final RailRecordReader records;
 public JdbcRailTicketStore(JdbcClient jdbc,TransactionTemplate tx,ObjectMapper json,Clock clock){this.jdbc=jdbc;this.tx=tx;this.json=json;this.clock=clock;this.records=new RailRecordReader(json);}
 private DomainFailure missing(){return new DomainFailure(NOT_FOUND,"Rail resource not found.");}
 public Optional<UUID> replay(UUID owner,String operation,String key,String fingerprint){return jdbc.sql("select fingerprint,resource_id from rail_ticket_command where customer_id=:owner and operation=:op and command_key=:key").param("owner",owner).param("op",operation).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"This key was used for different rail inputs.");return r.getObject(2,UUID.class);}).optional();}
 private boolean claim(UUID owner,String operation,String key,String fingerprint,UUID resource,UUID command){return jdbc.sql("insert into rail_ticket_command(id,customer_id,operation,command_key,fingerprint,resource_id) values(:id,:owner,:op,:key,:fingerprint,:resource) on conflict(customer_id,operation,command_key) do nothing").param("id",command).param("owner",owner).param("op",operation).param("key",key).param("fingerprint",fingerprint).param("resource",resource).update()==1;}
 private Quote ownedQuote(UUID owner,UUID id){return jdbc.sql("select payload::text from rail_ticket_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->json.readValue(s,Quote.class)).orElseThrow(this::missing);}
 public QuoteDetails quote(UUID owner,UUID id){var q=ownedQuote(owner,id);Instant accepted=jdbc.sql("select accepted_at from rail_ticket_acceptance where quote_id=:id").param("id",id).query((r,n)->r.getTimestamp(1).toInstant()).optional().orElse(null);UUID booking=jdbc.sql("select id from rail_ticket_booking where quote_id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(UUID.class).optional().orElse(null);return new QuoteDetails(q,accepted,booking,q.expired(clock.instant()));}
 public Quote createQuote(Quote q,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID command=UUID.randomUUID();if(!claim(q.owner(),"QUOTE",key,fingerprint,q.id(),command))return ownedQuote(q.owner(),replay(q.owner(),"QUOTE",key,fingerprint).orElseThrow());q.valid(clock.instant());jdbc.sql("insert into rail_ticket_quote(id,customer_id,created_at,expires_at,payload) values(:id,:owner,:created,:expires,cast(:payload as jsonb))").param("id",q.id()).param("owner",q.owner()).param("created",Timestamp.from(q.createdAt())).param("expires",Timestamp.from(q.expiresAt())).param("payload",json.writeValueAsString(q)).update();event(q.id(),1,"RailQuoteCreated",command,correlation,"CREATED","N/A","N/A","N/A");return q;});}
 public void accept(UUID owner,UUID id,int version,String key,String fingerprint,UUID correlation){tx.executeWithoutResult(t->{UUID command=UUID.randomUUID();if(!claim(owner,"ACCEPT",key,fingerprint,id,command)){replay(owner,"ACCEPT",key,fingerprint).orElseThrow();return;}jdbc.sql("select id from rail_ticket_quote where id=:id and customer_id=:owner for update").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var q=ownedQuote(owner,id);if(version!=q.version())throw new DomainFailure(QUOTE_VERSION_CONFLICT,"Accept the exact rail quote version.");q.valid(clock.instant());if(jdbc.sql("insert into rail_ticket_acceptance(quote_id,accepted_at,version) values(:id,:now,1) on conflict(quote_id) do nothing").param("id",id).param("now",Timestamp.from(clock.instant())).update()==1)event(id,2,"RailQuoteAccepted",command,correlation,"ACCEPTED","N/A","N/A","N/A");});}
 public Booking createBooking(UUID owner,UUID quoteId,int version,Scenario scenario,String key,String fingerprint,UUID correlation){return tx.execute(t->{UUID id=UUID.randomUUID(),command=UUID.randomUUID();if(!claim(owner,"BOOK",key,fingerprint,id,command))return booking(owner,replay(owner,"BOOK",key,fingerprint).orElseThrow());jdbc.sql("select id from rail_ticket_quote where id=:id and customer_id=:owner for update").param("id",quoteId).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var q=quote(owner,quoteId);if(q.quote().version()!=version)throw new DomainFailure(QUOTE_VERSION_CONFLICT,"Rail quote version changed.");if(q.acceptedAt()==null)throw new DomainFailure(QUOTE_NOT_ACCEPTED,"Accept this rail quote first.");if(q.bookingId()!=null)throw new DomainFailure(BOOKING_CONFLICT,"This quote already has a rail booking. Open My rail trips to recover it.");var b=Booking.create(id,q.quote(),q.acceptedAt(),scenario,command,correlation,clock.instant());jdbc.sql("insert into rail_ticket_booking(id,quote_id,customer_id,version,created_at,updated_at,status,payload) values(:id,:quote,:owner,1,:created,:updated,:status,cast(:payload as jsonb))").param("id",id).param("quote",quoteId).param("owner",owner).param("created",Timestamp.from(b.createdAt())).param("updated",Timestamp.from(b.updatedAt())).param("status",b.status().name()).param("payload",json.writeValueAsString(b)).update();jdbc.sql("insert into rail_ticket_work(booking_id,state) values(:id,'READY')").param("id",id).update();bookingEvent(b,"RailBookingCreated");return b;});}
 public Booking pnr(UUID owner,String pnr){return jdbc.sql("select payload::text from rail_ticket_booking where customer_id=:owner and payload->>'supplierReference'=:pnr").param("owner",owner).param("pnr",pnr).query(String.class).optional().map(v->records.booking(v)).orElseThrow(this::missing);}
 public Booking booking(UUID owner,UUID id){return jdbc.sql("select payload::text from rail_ticket_booking where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->records.booking(s)).orElseThrow(this::missing);}
 private Booking lockBooking(UUID owner,UUID id){jdbc.sql("select id from rail_ticket_booking where id=:id and customer_id=:owner for update").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);return booking(owner,id);}
 public Page list(UUID owner,UUID after){Instant at=Instant.MAX;UUID cursor=new UUID(-1,-1);if(after!=null){var b=booking(owner,after);at=b.createdAt();cursor=b.id();}var sql=after==null?"select payload::text from rail_ticket_booking where customer_id=:owner order by created_at desc,id desc limit 21":"select payload::text from rail_ticket_booking where customer_id=:owner and (created_at,id)<(:at,:cursor) order by created_at desc,id desc limit 21";var query=jdbc.sql(sql).param("owner",owner);if(after!=null)query.param("at",Timestamp.from(at)).param("cursor",cursor);var list=query.query(String.class).list().stream().map(s->records.booking(s)).toList();return new Page(list.stream().limit(20).toList(),list.size()>20?list.get(19).id():null);}
 private CancellationQuote readCancellationQuote(UUID owner,UUID id){return jdbc.sql("select payload::text from rail_ticket_cancellation_quote where id=:id and customer_id=:owner").param("id",id).param("owner",owner).query(String.class).optional().map(s->records.cancellation(s)).orElseThrow(this::missing);}
 public CancellationQuote cancellationQuote(UUID owner,UUID id,String key,UUID correlation){return tx.execute(t->{UUID qid=UUID.randomUUID(),command=UUID.randomUUID();if(!claim(owner,"CANCEL_QUOTE",key,id.toString(),qid,command))return readCancellationQuote(owner,replay(owner,"CANCEL_QUOTE",key,id.toString()).orElseThrow());var b=lockBooking(owner,id);var q=b.cancellationQuote(qid,clock.instant());jdbc.sql("insert into rail_ticket_cancellation_quote(id,booking_id,customer_id,payload) values(:id,:booking,:owner,cast(:payload as jsonb))").param("id",qid).param("booking",id).param("owner",owner).param("payload",json.writeValueAsString(q)).update();return q;});}
 public Booking cancel(UUID owner,UUID id,UUID quoteId,boolean delay,boolean loss,String key,String fingerprint,UUID correlation,boolean passengerAware){return tx.execute(t->{UUID command=UUID.randomUUID();if(!claim(owner,"CANCEL",key,fingerprint,id,command))return booking(owner,replay(owner,"CANCEL",key,fingerprint).orElseThrow());jdbc.sql("select w.booking_id from rail_ticket_work w join rail_ticket_booking b on b.id=w.booking_id where b.id=:id and b.customer_id=:owner for update of w").param("id",id).param("owner",owner).query(UUID.class).optional().orElseThrow(this::missing);var b=lockBooking(owner,id);var q=readCancellationQuote(owner,quoteId);if(!passengerAware){b.legacyAllowed();if(q.passengerIndexes()!=null)throw new DomainFailure(BOOKING_CONFLICT,"Use v2 for passenger-aware cancellation.");}if(!q.bookingId().equals(id))throw new DomainFailure(BOOKING_CONFLICT,"Cancellation quote belongs to another rail booking.");var next=b.cancel(new Cancellation(q,delay,loss,command),clock.instant());saveBooking(next,b.version());jdbc.sql("update rail_ticket_work set state='READY',attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();bookingEvent(next,"RailCancellationRequested");return next;});}
 private void saveBooking(Booking b,long expected){if(jdbc.sql("update rail_ticket_booking set version=:version,updated_at=:now,status=:status,payload=cast(:payload as jsonb) where id=:id and version=:previous").param("version",b.version()).param("now",Timestamp.from(b.updatedAt())).param("status",b.status().name()).param("payload",json.writeValueAsString(b)).param("id",b.id()).param("previous",expected).update()!=1)throw new DomainFailure(BOOKING_CONFLICT,"Concurrent rail update; reload status.");}
 public Optional<Claim> claim(){return tx.execute(t->{var id=jdbc.sql("select booking_id from rail_ticket_work where state in('READY','RUNNING') and next_at<=clock_timestamp() and (lease_until is null or lease_until<clock_timestamp()) order by next_at,booking_id for update skip locked limit 1").query(UUID.class).optional();if(id.isEmpty())return Optional.empty();UUID token=UUID.randomUUID();int attempts=jdbc.sql("update rail_ticket_work set state='RUNNING',attempts=attempts+1,lease_token=:token,lease_until=clock_timestamp()+interval '15 seconds' where booking_id=:id returning attempts").param("token",token).param("id",id.get()).query(Integer.class).single();Booking b=records.booking(jdbc.sql("select payload::text from rail_ticket_booking where id=:id").param("id",id.get()).query(String.class).single());return Optional.of(new Claim(b,token,attempts));});}
 private boolean owns(Claim c){return jdbc.sql("select booking_id from rail_ticket_work where booking_id=:id and state='RUNNING' and lease_token=:token and lease_until>clock_timestamp() for update").param("id",c.booking().id()).param("token",c.token()).query(UUID.class).optional().isPresent();}
 public boolean complete(Claim c,Booking next){return tx.execute(t->{if(!owns(c))return false;var current=lockBooking(next.quote().owner(),next.id());if(current.version()!=c.booking().version())return false;if(next.step()==Step.REVIEW)jdbc.sql("insert into rail_ticket_review_checkpoint(booking_id,review_version,payload) values(:id,:version,cast(:payload as jsonb))").param("id",next.id()).param("version",next.version()).param("payload",json.writeValueAsString(current)).update();saveBooking(next,current.version());jdbc.sql("update rail_ticket_work set state=:state,attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("state",next.step()==Step.REVIEW?"REVIEW":next.terminal()?"DONE":"READY").param("id",next.id()).update();if(next.step()==Step.DONE&&next.cancellation()!=null){var record=new CancellationResult(next.cancellation().quote().id(),next.cancellationScope(),next.cancellation().quote().refundAmount(),next.refund(),next.refundReference(),next.updatedAt());jdbc.sql("insert into rail_ticket_cancellation_result(quote_id,booking_id,payload) values(:quote,:booking,cast(:payload as jsonb)) on conflict(quote_id) do nothing").param("quote",record.quoteId()).param("booking",next.id()).param("payload",json.writeValueAsString(record)).update();}bookingEvent(next,next.passengerChanges()&&next.cancelledPassengerIndexes().size()>current.cancelledPassengerIndexes().size()?"RailPassengersCancelled":next.refund()==Refund.SUCCEEDED?"RailRefundCompleted":next.status()==Status.ISSUED?"RailTicketIssued":next.refund()==Refund.SUCCEEDED?"RailRefundCompleted":next.status()==Status.CANCELLED?"RailBookingCancelled":next.status()==Status.FAILED?"RailBookingFailed":next.status()==Status.REVIEW?"RailReconciliationRequired":"RailWorkflowProgressed");return true;});}
 public void retry(Claim c){int limit=c.booking().step()==Step.REFUND_STATUS?20:5;if(c.attempts()>=limit){complete(c,c.booking().review(clock.instant()));return;}tx.executeWithoutResult(t->{if(!owns(c))return;jdbc.sql("update rail_ticket_work set state='READY',lease_token=null,lease_until=null,next_at=clock_timestamp()+(:delay*interval '1 millisecond') where booking_id=:id").param("id",c.booking().id()).param("delay",Math.min(8000,c.attempts()*2000)+Math.floorMod(c.booking().id().hashCode(),500)).update();});}
 private void bookingEvent(Booking b,String type){event(b.id(),b.version(),type,b.cancellation()==null?b.commandId():b.cancellation().commandId(),b.correlationId(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name());}
 private void event(UUID aggregate,long version,String type,UUID cause,UUID correlation,String status,String payment,String reservation,String refund){UUID id=UUID.randomUUID();var payload=Map.of("status",status,"payment",payment,"reservation",reservation,"refund",refund);var body=new LinkedHashMap<String,Object>();body.put("eventId",id);body.put("aggregateId",aggregate);body.put("aggregateVersion",version);body.put("eventType",type);body.put("schemaVersion",1);body.put("producer","railtickets");body.put("mode","MOCK");body.put("occurredAt",clock.instant());body.put("correlationId",correlation);body.put("causationId",cause);body.put("payload",payload);jdbc.sql("insert into rail_ticket_outbox(id,aggregate_id,aggregate_version,event_type,envelope) values(:id,:aggregate,:version,:type,cast(:payload as jsonb))").param("id",id).param("aggregate",aggregate).param("version",version).param("type",type).param("payload",json.writeValueAsString(body)).update();}
 public List<Event> timeline(UUID owner,UUID id){booking(owner,id);return jdbc.sql("select envelope::text from rail_ticket_outbox where aggregate_id=:id order by aggregate_version limit 50").param("id",id).query(String.class).list().stream().map(s->{var n=json.readTree(s);var p=n.get("payload");return new Event(UUID.fromString(n.get("eventId").asString()),n.get("eventType").asString(),n.get("aggregateVersion").asLong(),Instant.parse(n.get("occurredAt").asString()),p.get("status").asString(),p.get("payment").asString(),p.get("reservation").asString(),p.get("refund").asString());}).toList();}
 public Voucher readVoucher(UUID owner,UUID id){return tx.execute(t->{var b=lockBooking(owner,id);b.legacyAllowed();b.voucherAllowed();return voucherRecord(id).orElseThrow(this::missing);});}
 private Optional<Voucher> voucherRecord(UUID id){return jdbc.sql("select payload::text from rail_ticket_voucher where booking_id=:id").param("id",id).query(String.class).optional().map(s->records.voucher(s));}
 public Voucher voucher(UUID owner,UUID id,String key,UUID correlation){return tx.execute(t->{var b=lockBooking(owner,id);b.legacyAllowed();b.voucherAllowed();UUID command=UUID.randomUUID();if(!claim(owner,"VOUCHER",key,id.toString(),id,command)){replay(owner,"VOUCHER",key,id.toString()).orElseThrow();return voucherRecord(id).orElseThrow();}var prior=voucherRecord(id);if(prior.isPresent())return prior.get();var text=new StringBuilder("TRAVBOOK MOCK RAIL TICKET SUMMARY\nNOT VALID FOR TRAVEL. NO REAL RESERVATION OR PAYMENT.\n");var journey=b.quote().selection().journey();text.append("Booking: ").append(id).append("\nMOCK PNR: ").append(b.supplierReference()).append("\nTicket status: ").append(b.reservation()).append("\nRAC/WAITLIST DOES NOT GUARANTEE A CONFIRMED BERTH. No berth is assigned by this simulator.\nTrain: ").append(journey.number()).append(' ').append(journey.name()).append("\nRoute: ").append(journey.origin().name()).append(" → ").append(journey.destination().name()).append("\nDeparture: ").append(journey.departure()).append("\nArrival: ").append(journey.arrival()).append("\nClass: ").append(b.quote().selection().availability().travelClass()).append("\nQuota: ").append(b.quote().selection().availability().quota()).append("\nBoarding: ").append(b.quote().selection().boardingStation()).append("\n");for(var passenger:b.quote().selection().passengers())text.append("Passenger: ").append(passenger.givenName()).append(' ').append(passenger.familyName()).append("; requested berth: ").append(passenger.berthPreference()).append(" (not guaranteed)\n");text.append("Total INR ").append(b.quote().selection().total().amount().toPlainString()).append("\n").append(com.travbook.railtickets.domain.model.RailTicket.CANCELLATION).append("\n");byte[] bytes=text.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>32768)throw new IllegalStateException("Voucher size exceeded");String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}var v=new Voucher(UUID.randomUUID(),id,clock.instant(),hash,bytes.length,text.toString());jdbc.sql("insert into rail_ticket_voucher(id,booking_id,payload) values(:id,:booking,cast(:payload as jsonb))").param("id",v.id()).param("booking",id).param("payload",json.writeValueAsString(v)).update();event(v.id(),1,"RailVoucherCreated",command,correlation,"CREATED","N/A","N/A","N/A");return v;});}

 public java.util.List<com.travbook.shared.domain.Recovery.Case> reviews(int page){return jdbc.sql("select id from rail_ticket_booking where status='REVIEW' order by updated_at,id limit 20 offset :offset").param("offset",page*20).query(UUID.class).list().stream().map(this::review).toList();}
 private Booking reviewBooking(UUID id){return jdbc.sql("select payload::text from rail_ticket_booking where id=:id").param("id",id).query(String.class).optional().map(p->records.booking(p)).orElseThrow(this::missing);}
 public com.travbook.shared.domain.Recovery.Case review(UUID id){var b=reviewBooking(id);var actions=jdbc.sql("select payload::text from rail_ticket_recovery_action where booking_id=:id order by created_at,id limit 3").param("id",id).query(String.class).list().stream().map(p->json.readValue(p,com.travbook.shared.domain.Recovery.Action.class)).toList();boolean available=b.status()==Status.REVIEW&&actions.size()<3&&jdbc.sql("select count(*) from rail_ticket_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",b.version()).query(Integer.class).single()==1;return new com.travbook.shared.domain.Recovery.Case(id,b.version(),b.status().name(),b.payment().name(),b.reservation().name(),b.refund().name(),available?checkpoint(id,b.version()).step().name():b.step().name(),available,b.updatedAt(),actions);}
 public Booking checkpoint(UUID id,long version){return jdbc.sql("select payload::text from rail_ticket_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",version).query(String.class).optional().map(p->records.booking(p)).orElseThrow(()->new DomainFailure(BOOKING_CONFLICT,"No saved recovery checkpoint; legacy review requires investigation."));}
 public Optional<com.travbook.shared.domain.Recovery.Action> recoveryReplay(String actor,String key,String fingerprint){return jdbc.sql("select fingerprint,payload::text from rail_ticket_recovery_action where actor=:actor and command_key=:key").param("actor",actor).param("key",key).query((r,n)->{if(!r.getString(1).equals(fingerprint))throw new DomainFailure(IDEMPOTENCY_CONFLICT,"Recovery key was used for different inputs.");return json.readValue(r.getString(2),com.travbook.shared.domain.Recovery.Action.class);}).optional();}
 public com.travbook.shared.domain.Recovery.Action resume(UUID id,long version,String actor,com.travbook.shared.domain.Recovery.Reason reason,String key,String fingerprint,UUID correlation){return tx.execute(t->{jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","rail_ticket-recovery:"+actor+":"+key).query((r,n)->true).single();var replay=recoveryReplay(actor,key,fingerprint);if(replay.isPresent())return replay.get();jdbc.sql("select booking_id from rail_ticket_work where booking_id=:id for update").param("id",id).query(UUID.class).optional().orElseThrow(this::missing);var original=reviewBooking(id);var current=lockBooking(original.quote().owner(),id);if(current.status()!=Status.REVIEW||current.version()!=version||!review(id).recoverable())throw new DomainFailure(BOOKING_CONFLICT,"Review changed, lacks a checkpoint, or exhausted its three recovery attempts.");var next=current.resumeFrom(checkpoint(id,version),clock.instant());var action=new com.travbook.shared.domain.Recovery.Action(UUID.randomUUID(),id,next.version(),actor,reason,clock.instant());jdbc.sql("insert into rail_ticket_recovery_action(id,booking_id,actor,command_key,fingerprint,created_at,payload) values(:id,:booking,:actor,:key,:fingerprint,:at,cast(:payload as jsonb))").param("id",action.id()).param("booking",id).param("actor",actor).param("key",key).param("fingerprint",fingerprint).param("at",Timestamp.from(action.createdAt())).param("payload",json.writeValueAsString(action)).update();saveBooking(next,current.version());jdbc.sql("update rail_ticket_work set state='READY',attempts=0,next_at=clock_timestamp(),lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();event(id,next.version(),"RailReconciliationResumed",action.id(),correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name());return action;});}

 public CancellationQuote passengerCancellationQuote(UUID owner,UUID id,List<Integer> indexes,String key,UUID correlation){String fingerprint=id+":"+indexes;return tx.execute(t->{UUID qid=UUID.randomUUID(),command=UUID.randomUUID();if(!claim(owner,"PASSENGER_QUOTE",key,fingerprint,qid,command))return readCancellationQuote(owner,replay(owner,"PASSENGER_QUOTE",key,fingerprint).orElseThrow());var q=lockBooking(owner,id).passengerCancellationQuote(qid,indexes,clock.instant());jdbc.sql("insert into rail_ticket_cancellation_quote(id,booking_id,customer_id,payload) values(:id,:booking,:owner,cast(:payload as jsonb))").param("id",qid).param("booking",id).param("owner",owner).param("payload",json.writeValueAsString(q)).update();return q;});}
 public PassengerDetails details(UUID owner,UUID id){return tx.execute(t->{var b=lockBooking(owner,id);return new PassengerDetails(b,cancellations(owner,id));});}
 public List<CancellationResult> cancellations(UUID owner,UUID id){booking(owner,id);return jdbc.sql("select payload::text from rail_ticket_cancellation_result where booking_id=:id order by created_at,quote_id").param("id",id).query(String.class).list().stream().map(p->json.readValue(p,CancellationResult.class)).toList();}
 private Optional<Voucher> passengerDocument(UUID id,int revision){return jdbc.sql("select payload::text from rail_ticket_document_revision where booking_id=:id and revision=:revision").param("id",id).param("revision",revision).query(String.class).optional().map(p->records.voucher(p));}
 public Voucher readPassengerVoucher(UUID owner,UUID id,int revision){return tx.execute(t->{var b=lockBooking(owner,id);b.voucherAllowed();if(revision!=b.cancelledPassengerIndexes().size())throw new DomainFailure(BOOKING_CONFLICT,"This document revision is no longer current.");return passengerDocument(id,revision).orElseThrow(this::missing);});}
 public Voucher passengerVoucher(UUID owner,UUID id,String key,UUID correlation){return tx.execute(t->{var b=lockBooking(owner,id);b.voucherAllowed();int revision=b.cancelledPassengerIndexes().size();UUID command=UUID.randomUUID();if(!claim(owner,"DOCUMENT_V2",key,id+":"+revision,id,command)){replay(owner,"DOCUMENT_V2",key,id+":"+revision).orElseThrow();return passengerDocument(id,revision).orElseThrow();}var prior=passengerDocument(id,revision);if(prior.isPresent())return prior.get();var text=new StringBuilder("TRAVBOOK MOCK RAIL TICKET SUMMARY\nNOT VALID FOR TRAVEL. NO REAL RESERVATION OR PAYMENT.\n");var journey=b.quote().selection().journey();text.append("Booking: ").append(id).append("\nMOCK PNR: ").append(b.supplierReference()).append("\nTicket status: ").append(b.reservation()).append("\nRAC/WAITLIST DOES NOT GUARANTEE A CONFIRMED BERTH. No berth is assigned by this simulator.\nTrain: ").append(journey.number()).append(' ').append(journey.name()).append("\nRoute: ").append(journey.origin().name()).append(" → ").append(journey.destination().name()).append("\nDeparture: ").append(journey.departure()).append("\nArrival: ").append(journey.arrival()).append("\nClass: ").append(b.quote().selection().availability().travelClass()).append("\nQuota: ").append(b.quote().selection().availability().quota()).append("\nBoarding: ").append(b.quote().selection().boardingStation()).append("\n");for(int index=0;index<b.quote().selection().passengers().size();index++){var passenger=b.quote().selection().passengers().get(index);text.append(b.cancelledPassengerIndexes().contains(index)?"CANCELLED — ":"ACTIVE — ").append("Passenger: ").append(passenger.givenName()).append(' ').append(passenger.familyName()).append("; requested berth: ").append(passenger.berthPreference()).append(" (not guaranteed)\n");}text.append("Passenger state revision: ").append(revision).append("\nOriginal booking total INR ").append(b.quote().selection().total().amount().toPlainString()).append("\n").append(com.travbook.railtickets.domain.model.RailTicket.CANCELLATION).append("\n");byte[] bytes=text.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>32768)throw new IllegalStateException("Voucher size exceeded");String hash;try{hash=HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(bytes));}catch(Exception e){throw new IllegalStateException(e);}var v=new Voucher(UUID.randomUUID(),id,clock.instant(),hash,bytes.length,text.toString(),revision);jdbc.sql("insert into rail_ticket_document_revision(id,booking_id,revision,payload) values(:id,:booking,:revision,cast(:payload as jsonb))").param("id",v.id()).param("booking",id).param("revision",revision).param("payload",json.writeValueAsString(v)).update();event(v.id(),1,"RailVoucherCreated",command,correlation,"CREATED","N/A","N/A","N/A");return v;});}

 public Booking legacyReview(UUID id,long version){var b=reviewBooking(id);if(b.status()!=Status.REVIEW||b.version()!=version||review(id).actions().size()>=3||jdbc.sql("select count(*) from rail_ticket_review_checkpoint where booking_id=:id and review_version=:version").param("id",id).param("version",version).query(Integer.class).single()!=0)throw new DomainFailure(BOOKING_CONFLICT,"Use saved checkpoint recovery, or refresh the current review.");return b;}
 public com.travbook.shared.domain.Recovery.Action reconcileLegacy(UUID id,long version,String actor,com.travbook.shared.domain.Recovery.Reason reason,String key,String fingerprint,UUID correlation,com.travbook.shared.domain.Recovery.Proof proof){return tx.execute(t->{jdbc.sql("select pg_advisory_xact_lock(hashtextextended(:key,0))").param("key","rail_ticket-recovery:"+actor+":"+key).query((r,n)->true).single();var replay=recoveryReplay(actor,key,fingerprint);if(replay.isPresent())return replay.get();jdbc.sql("select booking_id from rail_ticket_work where booking_id=:id for update").param("id",id).query(UUID.class).optional().orElseThrow(this::missing);var original=reviewBooking(id);lockBooking(original.quote().owner(),id);var current=legacyReview(id,version);var next=current.reconcileLegacy(proof,clock.instant());var action=new com.travbook.shared.domain.Recovery.Action(UUID.randomUUID(),id,next.version(),actor,reason,clock.instant());jdbc.sql("insert into rail_ticket_recovery_action(id,booking_id,actor,command_key,fingerprint,created_at,payload) values(:id,:booking,:actor,:key,:fingerprint,:at,cast(:payload as jsonb))").param("id",action.id()).param("booking",id).param("actor",actor).param("key",key).param("fingerprint",fingerprint).param("at",Timestamp.from(action.createdAt())).param("payload",json.writeValueAsString(action)).update();jdbc.sql("insert into rail_ticket_legacy_proof(action_id,booking_id,prior_version,proof) values(:action,:booking,:version,cast(:proof as jsonb))").param("action",action.id()).param("booking",id).param("version",version).param("proof",json.writeValueAsString(proof)).update();saveBooking(next,version);jdbc.sql("update rail_ticket_work set state='DONE',attempts=0,lease_token=null,lease_until=null where booking_id=:id").param("id",id).update();if(next.cancellation()!=null){var result=new CancellationResult(next.cancellation().quote().id(),next.cancellationScope(),next.cancellation().quote().refundAmount(),next.refund(),next.refundReference(),next.updatedAt());jdbc.sql("insert into rail_ticket_cancellation_result(quote_id,booking_id,payload) values(:quote,:booking,cast(:payload as jsonb)) on conflict(quote_id) do nothing").param("quote",result.quoteId()).param("booking",id).param("payload",json.writeValueAsString(result)).update();}event(id,next.version(),"RailLegacyOutcomeReconciled",action.id(),correlation,next.status().name(),next.payment().name(),next.reservation().name(),next.refund().name());return action;});}
}
